#include <stdio.h>
#include <stdlib.h>

/* The same list as the Rust version, with malloc and free by hand.
   Every step is logged as an event, so the player can draw it. */
struct Node {
    int id;
    int value;
    struct Node *next;
};

int events = 0;
void event(const char *json) {
    printf(events++ ? ",%s" : "%s", json);
}
char buf[200];

struct Node *cons(int id, int value, struct Node *next) {
    struct Node *n = malloc(sizeof(struct Node));
    n->id = id; n->value = value; n->next = next;
    snprintf(buf, sizeof buf, "{\"kind\":\"alloc\",\"id\":%d,\"value\":%d}", id, value); event(buf);
    if (next) { snprintf(buf, sizeof buf, "{\"kind\":\"link\",\"from\":%d,\"to\":%d}", id, next->id); event(buf); }
    return n;
}

int sum(struct Node *list) {
    int total = 0;
    for (struct Node *n = list; n; n = n->next) total += n->value;
    return total;
}

/* Free every node, head first. Nothing stops anyone using `list` afterwards. */
void free_list(struct Node *list) {
    while (list) {
        struct Node *next = list->next;
        snprintf(buf, sizeof buf, "{\"kind\":\"free\",\"id\":%d}", list->id); event(buf);
        free(list);
        list = next;
    }
}

int main() {
    printf("__NB_SET__ {\"key\":\"own\",\"value\":{\"lang\":\"C\",\"events\":[");
    struct Node *list = cons(1, 10, cons(2, 20, cons(3, 30, NULL)));
    event("{\"kind\":\"bind\",\"var\":\"list\",\"to\":1}");
    event("{\"kind\":\"say\",\"text\":\"list points at the first node; who frees the nodes is up to you\"}");

    event("{\"kind\":\"borrow\",\"var\":\"sum(list)\",\"of\":\"list\"}");
    int total = sum(list);
    snprintf(buf, sizeof buf, "{\"kind\":\"say\",\"text\":\"sum(list) reads the nodes and gives %d\"}", total); event(buf);
    event("{\"kind\":\"unborrow\",\"var\":\"sum(list)\"}");

    struct Node *moved = list;   /* a copy of the pointer: both point at node 1 */
    event("{\"kind\":\"copy\",\"from\":\"list\",\"to\":\"moved\"}");
    event("{\"kind\":\"say\",\"text\":\"moved = list copies the pointer: two variables, one list\"}");

    free_list(moved);
    event("{\"kind\":\"say\",\"text\":\"free_list(moved) frees all three; list still holds the old address\"}");
    event("{\"kind\":\"say\",\"text\":\"reading list->value now is use after free: C compiles it without a word\"}");
    list = NULL; moved = NULL;
    event("{\"kind\":\"null\",\"var\":\"list\"}");
    event("{\"kind\":\"null\",\"var\":\"moved\"}");
    event("{\"kind\":\"say\",\"text\":\"setting both to NULL by hand is the fix; Rust does this check for you\"}");

    /* Growing an array: does the buffer move? */
    int cap = 4;
    int *data = malloc(cap * sizeof(int));
    int *other = malloc(16);                     /* something else on the heap, right after it */
    for (int i = 0; i < cap; i++) data[i] = (i + 1) * 10;
    int *first = &data[0];
    unsigned long before = (unsigned long)data;
    cap *= 2;
    data = realloc(data, cap * sizeof(int));
    unsigned long after = (unsigned long)data;
    int moved_buf = before != after;
    printf("],\"vec\":{\"capBefore\":4,\"capAfter\":%d,\"moved\":%s}}}\n", cap, moved_buf ? "true" : "false");

    printf("sum = %d\n", total);
    printf("events recorded: %d\n", events);
    printf("growing the array from 4 to %d ints %s the buffer\n", cap, moved_buf ? "MOVED" : "did not move");
    if (moved_buf) printf("so `first`, taken before the growth, now points at freed memory\n");
    (void)first;
    free(data); free(other);
    return 0;
}

// Replay the memory events and count the mistakes: leaks, double frees, dangling pointers.
const own = nb.get('own');
if (!own) return 'Run the cell above first.';

const alive = {}, freedTimes = {}, vars = {};
let doubleFrees = 0, worstDangling = 0;
const rows = [];
own.events.forEach((e, step) => {
  if (e.kind === 'alloc') alive[e.id] = true;
  if (e.kind === 'drop' || e.kind === 'free') {
    freedTimes[e.id] = (freedTimes[e.id] || 0) + 1;
    if (freedTimes[e.id] > 1) doubleFrees++;
    alive[e.id] = false;
  }
  if (e.kind === 'bind') vars[e.var] = e.to;
  if (e.kind === 'move') { vars[e.to] = vars[e.from]; delete vars[e.from]; }
  if (e.kind === 'copy') vars[e.to] = vars[e.from];
  if (e.kind === 'null' || e.kind === 'gone') delete vars[e.var];
  const live = Object.values(alive).filter(Boolean).length;
  const dangling = Object.values(vars).filter(id => alive[id] === false).length;
  worstDangling = Math.max(worstDangling, dangling);
  rows.push({ step: step + 1, count: live, what: 'nodes alive' });
  rows.push({ step: step + 1, count: dangling, what: 'dangling pointers' });
});

const allocated = Object.keys(alive).length;
const leaked = Object.values(alive).filter(Boolean).length;
console.log(own.lang + ': ' + allocated + ' nodes allocated, ' + Object.keys(freedTimes).length + ' freed');
console.log('leaks: ' + leaked + ', double frees: ' + doubleFrees);
console.log('most dangling pointers at once: ' + worstDangling + ', at the end: ' + rows.at(-1).count);
console.log('growing the array from ' + own.vec.capBefore + ' to ' + own.vec.capAfter + ': the buffer ' +
  (own.vec.moved ? 'moved, so any pointer into the old one dangles' : 'stayed put this time'));

return {
  $schema: 'https://vega.github.io/schema/vega-lite/v5.json',
  width: 'container',
  height: 220,
  title: own.lang + ': nodes alive and dangling pointers, step by step',
  data: { values: rows },
  mark: { type: 'line', interpolate: 'step-after', strokeWidth: 2 },
  encoding: {
    x: { field: 'step', type: 'quantitative' },
    y: { field: 'count', type: 'quantitative', title: null, scale: { domain: [0, 3] }, axis: { tickMinStep: 1 } },
    color: { field: 'what', type: 'nominal', title: null, scale: { domain: ['nodes alive', 'dangling pointers'], range: ['#a78bfa', '#ef4444'] } },
  },
};
